import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"NetPilot: One Binary, Every Answer","description":"The story of building NetPilot — a pure-Go network toolkit that compresses five admin tools into one static binary.","frontmatter":{"title":"NetPilot: One Binary, Every Answer","description":"The story of building NetPilot — a pure-Go network toolkit that compresses five admin tools into one static binary."},"headers":[],"relativePath":"en/vibe-stories/story-1/index.md","filePath":"en/vibe-stories/story-1/index.md"}`),a={name:`en/vibe-stories/story-1/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="netpilot-one-binary-every-answer" tabindex="-1">NetPilot: One Binary, Every Answer <a class="header-anchor" href="#netpilot-one-binary-every-answer" aria-label="Permalink to “NetPilot: One Binary, Every Answer”">​</a></h1><p>Every sysadmin has that folder of half-installed tools: one for port scanning, one for pinging, one for health checks, all with different flags and output formats. <strong>NetPilot</strong> (<a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">GitHub</a>) started when I got tired of being that sysadmin.</p><h2 id="the-constraint-that-shaped-it" tabindex="-1">The constraint that shaped it <a class="header-anchor" href="#the-constraint-that-shaped-it" aria-label="Permalink to “The constraint that shaped it”">​</a></h2><p>I gave myself one rule: <strong>the deliverable is a single static binary</strong>. No runtime, no dependencies, no installer. That single constraint decided the language (Go), the architecture (stdlib first), and the UX (subcommands that read like sentences). It also made the project the perfect testbed for agent-team development — the spec was crisp enough that <a href="/Usf/en/agentic/overview/">agents</a> could implement commands in parallel while I reviewed.</p><h2 id="what-building-it-taught-me" tabindex="-1">What building it taught me <a class="header-anchor" href="#what-building-it-taught-me" aria-label="Permalink to “What building it taught me”">​</a></h2><ul><li><strong>Concurrency design beats concurrency folklore</strong> — a worker pool with real timeouts outperformed three &quot;optimized&quot; drafts.</li><li><strong>Output is an API</strong> — stable JSON output turned the CLI into a building block other scripts (and agents) can consume.</li><li><strong>Restraint scales</strong> — five well-made commands beat thirty half-made ones.</li></ul><p>Today NetPilot is the first thing I deploy on any new box, and the standard by which I judge every CLI I build — including the ones agents build for me.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};